import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FiArrowRight, FiStar, FiBriefcase, FiUsers, FiCheck, FiTrendingUp, FiShield, FiAward, FiZap, FiClock, FiChevronLeft, FiChevronRight, FiSearch, FiCode, FiCpu, FiSmartphone, FiLayout, FiDatabase, FiServer, FiCloud, FiGitBranch, FiCheckCircle, FiLayers } from 'react-icons/fi';
import heroImg from '../assets/logo/hero-dark-tone-lg.webp';

const Home = () => {
  const navigate = useNavigate();
  const [currentTestimonial, setCurrentTestimonial] = useState(0);
  const [heroTab, setHeroTab] = useState('hire');
  const [heroSearch, setHeroSearch] = useState('');
  const [stats, setStats] = useState({ students: 0, projects: 0, success: 0, clients: 0 });

  // Animated Counter
  useEffect(() => {
    const targets = { students: 5247, projects: 1893, success: 95, clients: 428 };
    const duration = 2000;
    const steps = 50;
    const increment = {
      students: targets.students / steps,
      projects: targets.projects / steps,
      success: targets.success / steps,
      clients: targets.clients / steps
    };
    
    let current = 0;
    const timer = setInterval(() => {
      current++;
      setStats({
        students: Math.min(Math.floor(increment.students * current), targets.students),
        projects: Math.min(Math.floor(increment.projects * current), targets.projects),
        success: Math.min(Math.floor(increment.success * current), targets.success),
        clients: Math.min(Math.floor(increment.clients * current), targets.clients)
      });
      if (current >= steps) clearInterval(timer);
    }, duration / steps);
    
    return () => clearInterval(timer);
  }, []);

  // Auto-rotate testimonials
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTestimonial(prev => (prev + 1) % testimonials.length);
    }, 5000);
    return () => clearInterval(timer);
  }, []);

  const features = [
    { icon: <FiStar size={28}/>, title: 'AI-Powered Matching', desc: 'Smart algorithm matches students with projects for 95% success rate.', color: 'from-yellow-500 to-orange-600' },
    { icon: <FiShield size={28}/>, title: 'Secure Payments', desc: 'Payment protection with escrow. Money safe until completion.', color: 'from-green-500 to-emerald-600' },
    { icon: <FiZap size={28}/>, title: 'Instant Notifications', desc: 'Real-time updates on applications and project milestones.', color: 'from-blue-500 to-indigo-600' },
    { icon: <FiAward size={28}/>, title: 'Verified Profiles', desc: 'All users verified. Build trust with proven track records.', color: 'from-purple-500 to-pink-600' },
  ];

  const testimonials = [
    { name: 'Sarah Mitchell', role: 'Computer Science Student', avatar: 'SM', rating: 5, text: 'I landed my first freelance project within a week! Made $2,500 in my first month!', projects: 12 },
    { name: 'James Rodriguez', role: 'Design Student', avatar: 'JR', rating: 5, text: 'SkillBridge AI connected me with amazing projects that match my skills perfectly!', projects: 8 },
    { name: 'Emily Chen', role: 'Marketing Student', avatar: 'EC', rating: 5, text: 'Professional platform. Clients are serious and payments on time. Highly recommend!', projects: 15 },
    { name: 'Michael Kumar', role: 'Web Dev Student', avatar: 'MK', rating: 5, text: 'From zero to 10 completed projects! SkillBridge AI gave me real portfolio.', projects: 10 }
  ];

  return (
    <div className="overflow-x-hidden">

      {/* ANNOUNCEMENT BANNER */}
      <div style={{ maxWidth: '1400px', margin: '0 auto', padding: '0 24px' }}>
        <div style={{
          background: 'linear-gradient(90deg, #d1f7c4 0%, #e8f5e3 40%, #f5fbf2 70%, #fafdfb 100%)',
          borderRadius: '16px',
          padding: '24px 32px',
          marginTop: '40px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}>
          <p style={{ fontFamily: "'Plus Jakarta Sans', sans-serif", fontSize: '18px', color: '#181818', fontWeight: 550, margin: 0, lineHeight: '19.8px', letterSpacing: '0.36px' }}>
            Build your portfolio with real projects. Join 5,000+ students on SkillBridge AI.
          </p>
          <Link
            to="/register"
            style={{ fontFamily: "'Plus Jakarta Sans', sans-serif", fontSize: '18px', color: '#181818', fontWeight: 550, textDecoration: 'underline', whiteSpace: 'nowrap', display: 'flex', alignItems: 'center', gap: '6px', lineHeight: '19.8px', letterSpacing: '0.36px' }}
          >
            Get started <span style={{ fontSize: '20px', fontWeight: 300 }}>›</span>
          </Link>
        </div>
      </div>

      {/* HERO SECTION - Upwork Style */}
      <section style={{ maxWidth: '1400px', margin: '40px auto 0', padding: '0 24px' }}>
        <div style={{
          position: 'relative',
          borderRadius: '20px',
          overflow: 'hidden',
          minHeight: '560px',
          display: 'flex',
          alignItems: 'center',
        }}>
          {/* Background Image */}
          <img
            src={heroImg}
            alt=""
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              zIndex: 1,
            }}
          />
          {/* Dark Overlay */}
          <div style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            background: 'linear-gradient(90deg, rgba(0,30,0,0.65) 0%, rgba(0,30,0,0.35) 50%, rgba(0,0,0,0.1) 100%)',
            zIndex: 2,
          }} />

          {/* Content */}
          <div style={{ position: 'relative', zIndex: 3, padding: '64px', maxWidth: '680px' }}>
            <h1 style={{
              fontFamily: "'Plus Jakarta Sans', sans-serif",
              fontSize: '56px',
              fontWeight: 800,
              color: '#ffffff',
              lineHeight: 1.1,
              marginBottom: '20px',
              letterSpacing: '-0.5px',
            }}>
              Build your career,<br/>one project at a time
            </h1>

            <p style={{
              fontFamily: "'Plus Jakarta Sans', sans-serif",
              fontSize: '18px',
              fontWeight: 500,
              color: 'rgba(255,255,255,0.85)',
              lineHeight: 1.5,
              marginBottom: '36px',
              maxWidth: '520px',
            }}>
              Access real projects ready to help you learn and grow — matched to your skills with AI
            </p>

            {/* Tabs */}
            <div style={{
              display: 'flex',
              background: 'rgba(0,0,0,0.4)',
              borderRadius: '10rem',
              padding: '4px',
              marginBottom: '16px',
              maxWidth: '480px',
            }}>
              <button
                onClick={() => setHeroTab('hire')}
                style={{
                  flex: 1,
                  padding: '12px 24px',
                  borderRadius: '10rem',
                  border: 'none',
                  cursor: 'pointer',
                  fontFamily: "'Plus Jakarta Sans', sans-serif",
                  fontSize: '15px',
                  fontWeight: 600,
                  transition: 'all 0.2s',
                  background: heroTab === 'hire' ? '#ffffff' : 'transparent',
                  color: heroTab === 'hire' ? '#181818' : '#ffffff',
                }}
              >
                I want to hire
              </button>
              <button
                onClick={() => setHeroTab('work')}
                style={{
                  flex: 1,
                  padding: '12px 24px',
                  borderRadius: '10rem',
                  border: 'none',
                  cursor: 'pointer',
                  fontFamily: "'Plus Jakarta Sans', sans-serif",
                  fontSize: '15px',
                  fontWeight: 600,
                  transition: 'all 0.2s',
                  background: heroTab === 'work' ? '#ffffff' : 'transparent',
                  color: heroTab === 'work' ? '#181818' : '#ffffff',
                }}
              >
                I want to work
              </button>
            </div>

            {/* Search Bar */}
            <div style={{
              display: 'flex',
              alignItems: 'center',
              background: '#ffffff',
              borderRadius: '10rem',
              padding: '6px 6px 6px 20px',
              maxWidth: '480px',
            }}>
              <input
                type="text"
                value={heroSearch}
                onChange={(e) => setHeroSearch(e.target.value)}
                placeholder={heroTab === 'hire' ? 'Describe what you need to hire for...' : 'Search for projects...'}
                style={{
                  flex: 1,
                  border: 'none',
                  outline: 'none',
                  fontFamily: "'Plus Jakarta Sans', sans-serif",
                  fontSize: '15px',
                  color: '#181818',
                  background: 'transparent',
                }}
              />
              <button
                onClick={() => navigate('/browse')}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px',
                  padding: '12px 24px',
                  background: '#14A800',
                  color: '#ffffff',
                  border: 'none',
                  borderRadius: '10rem',
                  cursor: 'pointer',
                  fontFamily: "'Plus Jakarta Sans', sans-serif",
                  fontSize: '15px',
                  fontWeight: 600,
                }}
              >
                <FiSearch size={16} />
                Search
              </button>
            </div>

            {/* Quick Tags */}
            <div style={{ display: 'flex', gap: '10px', marginTop: '20px', flexWrap: 'wrap' }}>
              {['Web design', 'AI development', 'Video editing', 'Google Ads'].map((tag) => (
                <Link
                  key={tag}
                  to="/browse"
                  style={{
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: '6px',
                    padding: '8px 16px',
                    border: '1px solid rgba(255,255,255,0.4)',
                    borderRadius: '10rem',
                    color: '#ffffff',
                    fontSize: '13px',
                    fontFamily: "'Plus Jakarta Sans', sans-serif",
                    fontWeight: 500,
                    textDecoration: 'none',
                    transition: 'all 0.2s',
                  }}
                  onMouseEnter={(e) => { e.currentTarget.style.background = 'rgba(255,255,255,0.15)'; }}
                  onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; }}
                >
                  {tag} <FiArrowRight size={12} />
                </Link>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* AI MATCHING ILLUSTRATION SECTION */}
      <section style={{ padding: '80px 0', background: '#ffffff' }}>
        <div style={{ maxWidth: '1100px', margin: '0 auto', padding: '0 24px', display: 'flex', alignItems: 'center', gap: '60px', flexWrap: 'wrap' }}>

          {/* LEFT: Inline SVG Illustration */}
          <div style={{ flex: '1 1 320px', minWidth: '280px' }}>
            <svg viewBox="0 0 480 420" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ width: '100%' }}>
              <defs>
                <filter id="cardShadow" x="-20%" y="-20%" width="140%" height="150%">
                  <feDropShadow dx="0" dy="6" stdDeviation="10" floodColor="#00000014" />
                </filter>
              </defs>

              {/* BG */}
              <rect width="480" height="420" rx="24" fill="#f8fdf8" />
              <circle cx="240" cy="210" r="165" fill="#edf7eb" opacity="0.6" />

              {/* === LEFT: Student Profile Card === */}
              <rect x="18" y="95" width="148" height="230" rx="16" fill="white" filter="url(#cardShadow)" />
              {/* Avatar */}
              <circle cx="92" cy="145" r="30" fill="#14A800" />
              <text x="92" y="152" textAnchor="middle" fontSize="17" fill="white" fontWeight="700">JS</text>
              {/* Name bar */}
              <rect x="48" y="186" width="88" height="10" rx="5" fill="#e5e7eb" />
              {/* Role bar */}
              <rect x="60" y="202" width="64" height="8" rx="4" fill="#d1fae5" />
              {/* Skill chips */}
              <rect x="30" y="222" width="50" height="20" rx="10" fill="rgba(20,168,0,0.1)" />
              <text x="55" y="236" textAnchor="middle" fontSize="10" fill="#14A800" fontWeight="600">React</text>
              <rect x="86" y="222" width="58" height="20" rx="10" fill="rgba(59,130,246,0.1)" />
              <text x="115" y="236" textAnchor="middle" fontSize="10" fill="#3b82f6" fontWeight="600">Node.js</text>
              <rect x="30" y="248" width="52" height="20" rx="10" fill="rgba(139,92,246,0.1)" />
              <text x="56" y="262" textAnchor="middle" fontSize="10" fill="#8b5cf6" fontWeight="600">Python</text>
              <rect x="88" y="248" width="44" height="20" rx="10" fill="rgba(245,158,11,0.1)" />
              <text x="110" y="262" textAnchor="middle" fontSize="10" fill="#f59e0b" fontWeight="600">SQL</text>
              {/* CTA button */}
              <rect x="28" y="278" width="110" height="32" rx="10" fill="#14A800" />
              <text x="83" y="299" textAnchor="middle" fontSize="11" fill="white" fontWeight="700">View Profile →</text>

              {/* === Dashed lines: Left → Center === */}
              <line x1="168" y1="162" x2="202" y2="192" stroke="#14A800" strokeWidth="1.5" strokeDasharray="5,4" opacity="0.5" />
              <line x1="168" y1="210" x2="202" y2="210" stroke="#14A800" strokeWidth="1.5" strokeDasharray="5,4" opacity="0.5" />
              <line x1="168" y1="258" x2="202" y2="228" stroke="#14A800" strokeWidth="1.5" strokeDasharray="5,4" opacity="0.5" />

              {/* === CENTER: AI Badge === */}
              <circle cx="240" cy="210" r="40" fill="#14A800" filter="url(#cardShadow)" />
              <circle cx="240" cy="210" r="32" fill="none" stroke="white" strokeWidth="1.5" opacity="0.35" />
              <circle cx="240" cy="210" r="22" fill="none" stroke="white" strokeWidth="1" opacity="0.2" />
              <text x="240" y="205" textAnchor="middle" fontSize="14" fill="white" fontWeight="800">AI</text>
              <text x="240" y="222" textAnchor="middle" fontSize="9" fill="white" opacity="0.9" fontWeight="600">MATCH</text>

              {/* === Dashed lines: Center → Right === */}
              <line x1="280" y1="192" x2="314" y2="154" stroke="#14A800" strokeWidth="1.5" strokeDasharray="5,4" opacity="0.5" />
              <line x1="280" y1="210" x2="314" y2="210" stroke="#14A800" strokeWidth="1.5" strokeDasharray="5,4" opacity="0.5" />
              <line x1="280" y1="228" x2="314" y2="268" stroke="#14A800" strokeWidth="1.5" strokeDasharray="5,4" opacity="0.5" />

              {/* === RIGHT: Project Card 1 === */}
              <rect x="314" y="105" width="150" height="86" rx="14" fill="white" filter="url(#cardShadow)" />
              <rect x="330" y="120" width="8" height="8" rx="4" fill="#14A800" />
              <text x="344" y="129" fontSize="12" fill="#181818" fontWeight="700">Web Dev Project</text>
              <text x="330" y="148" fontSize="10" fill="#5e6d55">React · Node.js · MongoDB</text>
              <rect x="330" y="160" width="70" height="20" rx="10" fill="#14A800" />
              <text x="365" y="174" textAnchor="middle" fontSize="10" fill="white" fontWeight="700">95% Match</text>

              {/* === RIGHT: Project Card 2 === */}
              <rect x="314" y="206" width="150" height="86" rx="14" fill="white" filter="url(#cardShadow)" />
              <rect x="330" y="221" width="8" height="8" rx="4" fill="#0284c7" />
              <text x="344" y="230" fontSize="12" fill="#181818" fontWeight="700">AI/ML Internship</text>
              <text x="330" y="249" fontSize="10" fill="#5e6d55">Python · TensorFlow</text>
              <rect x="330" y="261" width="66" height="20" rx="10" fill="rgba(2,132,199,0.12)" />
              <text x="363" y="275" textAnchor="middle" fontSize="10" fill="#0284c7" fontWeight="700">82% Match</text>

              {/* === RIGHT: Project Card 3 === */}
              <rect x="314" y="307" width="150" height="80" rx="14" fill="white" filter="url(#cardShadow)" />
              <rect x="330" y="322" width="8" height="8" rx="4" fill="#8b5cf6" />
              <text x="344" y="331" fontSize="12" fill="#181818" fontWeight="700">UI/UX Design Task</text>
              <text x="330" y="350" fontSize="10" fill="#5e6d55">Figma · Prototyping</text>
              <rect x="330" y="362" width="60" height="20" rx="10" fill="rgba(139,92,246,0.12)" />
              <text x="360" y="376" textAnchor="middle" fontSize="10" fill="#8b5cf6" fontWeight="700">78% Match</text>
            </svg>
          </div>

          {/* RIGHT: Text Content */}
          <div style={{ flex: '1 1 300px' }}>
            <p style={{ fontFamily: "'Plus Jakarta Sans', sans-serif", fontSize: '12px', fontWeight: 700, color: '#14A800', letterSpacing: '2.5px', textTransform: 'uppercase', marginBottom: '16px', margin: '0 0 16px 0' }}>
              AI-POWERED PLATFORM
            </p>
            <h2 style={{ fontFamily: "'Plus Jakarta Sans', sans-serif", fontSize: '42px', fontWeight: 800, color: '#181818', lineHeight: 1.15, marginBottom: '20px', margin: '0 0 20px 0' }}>
              Smart matching,<br />built for students
            </h2>
            <p style={{ fontFamily: "'Plus Jakarta Sans', sans-serif", fontSize: '16px', color: '#5e6d55', lineHeight: 1.8, marginBottom: '36px', margin: '0 0 36px 0' }}>
              Our AI analyzes your skills and finds the best-fit projects automatically. No cold applying, no guessing — just the right match, every time.
            </p>
            {[
              'AI matches your skills to real projects instantly',
              'See your match score before you apply',
              'Built for final year & academic projects',
              'Open source · MERN + AI Stack',
            ].map((point, i) => (
              <div key={i} style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '16px' }}>
                <div style={{ width: '24px', height: '24px', borderRadius: '50%', background: '#14A800', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                  <FiCheck size={13} color="white" strokeWidth={3} />
                </div>
                <p style={{ fontFamily: "'Plus Jakarta Sans', sans-serif", fontSize: '15px', color: '#333', margin: 0 }}>{point}</p>
              </div>
            ))}
            <Link
              to="/register"
              style={{ display: 'inline-flex', alignItems: 'center', gap: '8px', marginTop: '12px', padding: '14px 32px', background: '#14A800', color: '#ffffff', borderRadius: '10rem', textDecoration: 'none', fontFamily: "'Plus Jakarta Sans', sans-serif", fontSize: '15px', fontWeight: 700 }}
            >
              Get Started Free <FiArrowRight size={16} />
            </Link>
          </div>

        </div>
      </section>

      {/* DESIGNED FOR STUDENTS AT - Trust Bar */}
      <section style={{ background: '#ffffff', padding: '40px 0', borderTop: '1px solid #e8ede8', borderBottom: '1px solid #e8ede8' }}>
        <div style={{ maxWidth: '1100px', margin: '0 auto', padding: '0 24px' }}>
          <p style={{
            textAlign: 'center',
            fontFamily: "'Plus Jakarta Sans', sans-serif",
            fontSize: '13px',
            fontWeight: 700,
            color: '#9e9e9e',
            letterSpacing: '2px',
            textTransform: 'uppercase',
            marginBottom: '32px',
          }}>
            DESIGNED FOR STUDENTS AT
          </p>
          <div style={{
            display: 'flex',
            flexWrap: 'wrap',
            justifyContent: 'center',
            alignItems: 'center',
            gap: '40px',
          }}>
            {[
              { label: 'B.E / B.Tech', icon: <FiCode size={20}/> },
              { label: 'MCA / BCA', icon: <FiCpu size={20}/> },
              { label: 'Computer Science', icon: <FiServer size={20}/> },
              { label: 'Information Technology', icon: <FiDatabase size={20}/> },
              { label: 'Final Year Projects', icon: <FiAward size={20}/> },
              { label: 'Skill Dev Courses', icon: <FiZap size={20}/> },
            ].map((item, i) => (
              <div key={i} style={{
                display: 'flex',
                alignItems: 'center',
                gap: '8px',
                color: '#555',
                fontFamily: "'Plus Jakarta Sans', sans-serif",
                fontSize: '16px',
                fontWeight: 700,
                opacity: 0.75,
              }}>
                <span style={{ color: '#14A800' }}>{item.icon}</span>
                {item.label}
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* FEATURES */}
      <section className="py-20 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16">
            <span className="px-4 py-2 bg-green-50 text-[#14A800] rounded-full text-sm font-bold uppercase" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>Why SkillBridge AI</span>
            <h2 className="text-5xl font-black text-[#181818] mt-6 mb-4" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>Everything You Need</h2>
            <p className="text-xl text-[#5e6d55] max-w-2xl mx-auto" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>Built for students. Every feature helps you land projects faster.</p>
          </div>
          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-8">
            {features.map((f, i) => (
              <div key={i} className="bg-white rounded-2xl p-8 hover:shadow-lg transition-all duration-300 border border-[#d5e0d5] hover:border-[#14A800] transform hover:-translate-y-2">
                <div className="w-16 h-16 bg-[#14A800] rounded-2xl flex items-center justify-center mb-6 text-white">
                  {f.icon}
                </div>
                <h3 className="text-xl font-black text-[#181818] mb-3" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>{f.title}</h3>
                <p className="text-[#5e6d55] leading-relaxed" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>{f.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* TESTIMONIALS */}
      <section className="py-20 bg-white border-t border-[#e0e0e0]">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-16">
            <span className="px-4 py-2 bg-green-50 text-[#14A800] rounded-full text-sm font-bold uppercase" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>Success Stories</span>
            <h2 className="text-5xl font-black mt-6 mb-4 text-[#181818]" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>Students Love Us</h2>
          </div>

          <div className="bg-white rounded-3xl p-10 border border-[#d5e0d5] shadow-sm">
            <div className="flex items-start space-x-6">
              <div className="w-20 h-20 bg-[#14A800] rounded-2xl flex items-center justify-center text-white text-2xl font-black flex-shrink-0">
                {testimonials[currentTestimonial].avatar}
              </div>
              <div className="flex-1">
                <div className="flex space-x-1 mb-4">
                  {[...Array(5)].map((_, i) => <FiStar key={i} className="text-[#14A800] fill-current" size={20}/>)}
                </div>
                <p className="text-2xl font-semibold mb-6 leading-relaxed text-[#181818]" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>{testimonials[currentTestimonial].text}</p>
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-lg font-black text-[#181818]">{testimonials[currentTestimonial].name}</p>
                    <p className="text-[#5e6d55]">{testimonials[currentTestimonial].role}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-3xl font-black text-[#14A800]">{testimonials[currentTestimonial].projects}</p>
                    <p className="text-[#5e6d55] text-sm">Projects</p>
                  </div>
                </div>
              </div>
            </div>

            {/* Navigation */}
            <div className="flex items-center justify-center space-x-4 mt-8">
              <button onClick={() => setCurrentTestimonial((currentTestimonial - 1 + testimonials.length) % testimonials.length)} className="p-3 border border-[#d5e0d5] hover:border-[#14A800] rounded-full transition-colors">
                <FiChevronLeft size={24} className="text-[#181818]"/>
              </button>
              <div className="flex space-x-2">
                {testimonials.map((_, i) => (
                  <button key={i} onClick={() => setCurrentTestimonial(i)} className={`h-2 rounded-full transition-all ${i === currentTestimonial ? 'bg-[#14A800] w-8' : 'bg-[#d5e0d5] w-2'}`}></button>
                ))}
              </div>
              <button onClick={() => setCurrentTestimonial((currentTestimonial + 1) % testimonials.length)} className="p-3 border border-[#d5e0d5] hover:border-[#14A800] rounded-full transition-colors">
                <FiChevronRight size={24} className="text-[#181818]"/>
              </button>
            </div>
          </div>
        </div>
      </section>

      {/* FINAL CTA */}
      <section className="bg-white py-20 border-t border-[#e0e0e0]">
        <div className="max-w-4xl mx-auto px-4 text-center">
          <h2 className="text-5xl lg:text-6xl font-black text-[#181818] mb-6" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>Ready to Start?</h2>
          <p className="text-xl text-[#5e6d55] mb-10" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>Join thousands of students building careers on SkillBridge AI.</p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <Link to="/register" className="px-10 py-5 bg-[#14A800] hover:bg-[#1dbf00] text-white rounded-[10rem] font-black text-lg hover:scale-105 transform transition-all" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>Create Free Account</Link>
            <Link to="/browse" className="px-10 py-5 border-2 border-[#181818] text-[#181818] rounded-[10rem] font-black text-lg hover:bg-[#181818] hover:text-white transition-all" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>Browse Projects</Link>
          </div>
        </div>
      </section>
    </div>
  );
};

export default Home;
